import com.holdmyspot.codexunleashed.scheduler.LinuxCgroup;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.time.Duration;
import java.util.Comparator;
import java.util.concurrent.TimeUnit;

public final class CgroupGate
{
    public static void main(String[] args) throws Exception
    {
        System.out.println("owner_module=" + LinuxCgroup.class.getModule().getName());
        System.out.println("owner_origin=" + LinuxCgroup.class.getProtectionDomain().getCodeSource().getLocation());
        Path parent = Path.of(args[0]);
        Path work = Path.of(args[1]);
        Path classes = Path.of(args[2]);
        if (args[3].equals("validation"))
        {
            try (var unexpected = LinuxCgroup.create(parent, Duration.ZERO))
            {
                throw new AssertionError("Zero termination timeout was accepted");
            }
            catch (IllegalArgumentException expected)
            {
                System.out.println("zero_timeout=rejected");
            }
            return;
        }

        for (String mode : new String[]{"terminate", "close", "interrupted-close"})
        {
            LinuxCgroup group = LinuxCgroup.create(parent, Duration.ofSeconds(5));
            Path directory = group.directory();
            Process child = null;
            try
            {
                check(group.isPopulated() == false, "New group is populated");
                Path nested = Files.createDirectory(directory.resolve("nested"));
                Path leaf = Files.createDirectory(nested.resolve("leaf"));
                Path marker = work.resolve(mode + ".ready");
                child = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
                    "-Djava.io.tmpdir=" + work, "-cp", classes.toString(), "CgroupFixture", leaf.toString(), marker.toString()).start();
                long start = System.nanoTime();
                while (Files.exists(marker) == false)
                {
                    if ((System.nanoTime() - start) >= Duration.ofSeconds(5).toNanos())
                        throw new AssertionError("Contained fixture readiness is missing");
                    Thread.sleep(10);
                }
                check(group.isPopulated(), "Live nested child was reported unpopulated");

                if (mode.equals("terminate"))
                {
                    group.terminate();
                    check(child.waitFor(5, TimeUnit.SECONDS), "Explicit termination did not end child");
                    check(group.isPopulated() == false, "Group remains populated after termination");
                }
                if (mode.equals("interrupted-close"))
                    Thread.currentThread().interrupt();
                group.close();
                if (mode.equals("interrupted-close"))
                    check(Thread.interrupted(), "Close lost the caller interrupt");
                check(child.waitFor(5, TimeUnit.SECONDS), "Close did not end child");
                check(child.exitValue() == 137, "Child did not retain SIGKILL exit status");
                check(Files.exists(directory) == false, "Owned group directory remains after close");
                group.close();
                try
                {
                    group.isPopulated();
                    throw new AssertionError("Closed population sampling was accepted");
                }
                catch (IllegalStateException expected)
                {
                }
                System.out.println(mode + "=passed");
            }
            finally
            {
                Thread.interrupted();
                if (child != null)
                {
                    child.destroyForcibly();
                    child.waitFor();
                    child.getInputStream().close();
                    child.getErrorStream().close();
                    child.getOutputStream().close();
                }
                if (Files.exists(directory))
                {
                    Files.writeString(directory.resolve("cgroup.kill"), "1");
                    try (var entries = Files.walk(directory))
                    {
                        for (Path path : entries.filter(p -> Files.isDirectory(p, LinkOption.NOFOLLOW_LINKS)).sorted(Comparator.reverseOrder()).toList())
                            Files.delete(path);
                    }
                }
            }
        }
    }

    private static void check(boolean accepted, String message)
    {
        if (accepted == false)
            throw new AssertionError(message);
    }
}

